using System;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using GameFoundation.MetaProgression;
[InitializeOnLoad]
public static class WorldCasualtyValidation
{
 const string Path="Assets/Editor/WorldLossesQA.unity";const BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;static WorldCasualtyPopup popup;static double started;static bool acknowledged,oldBackground;static object oldWrites;static FieldInfo writes;static Canvas canvas;
 static WorldCasualtyValidation(){EditorApplication.playModeStateChanged+=s=>{if(!SessionState.GetBool("WorldLossesQA",false))return;if(s==PlayModeStateChange.EnteredPlayMode)EditorApplication.delayCall+=Run;if(s==PlayModeStateChange.EnteredEditMode){EditorApplication.update-=Tick;EditorSceneManager.playModeStartScene=AssetDatabase.LoadAssetAtPath<SceneAsset>(SessionState.GetString("WorldLossesPrevious",""));AssetDatabase.DeleteAsset(Path);SessionState.SetBool("WorldLossesQA",false);}};}
 public static void Begin(){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);EditorSceneManager.SaveScene(scene,Path);EditorSceneManager.CloseScene(scene,true);SessionState.SetString("WorldLossesPrevious",AssetDatabase.GetAssetPath(EditorSceneManager.playModeStartScene));SessionState.SetString("WorldLossesResult","RUNNING");SessionState.SetBool("WorldLossesQA",true);EditorSceneManager.playModeStartScene=AssetDatabase.LoadAssetAtPath<SceneAsset>(Path);EditorApplication.isPlaying=true;}
 static void Check(bool v,string text){if(!v)throw new Exception(text);}
 static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,Private).GetValue(o);
 static ResourceType Resource(string name)=>AssetDatabase.LoadAssetAtPath<ResourceType>("Assets/Resources/ResourceTypes/"+name+".asset");
 static void Run(){try{
  var saves=typeof(GameFoundation.Saves.SaveSlotPrefs).Assembly.GetType("GameFoundation.Saves.GameSaveService");writes=saves.GetField("WritesSuspended",BindingFlags.NonPublic|BindingFlags.Static);oldWrites=writes.GetValue(null);writes.SetValue(null,true);oldBackground=Application.runInBackground;Application.runInBackground=true;
  WorldCasualties.Begin();var human=Resource("Human");var sword=Resource("Swordsman");var archer=Resource("Archer");var resources=new GameObject("QA inventory").AddComponent<GlobalResourceManager>();resources.SetResourceAmount(human,10);
  var resident=new GameObject("QA civilian");WorldCivilianTarget.Ensure(resident,human);resident.GetComponent<Health>().TakeDamage(100000,DamageType.Physical);WorldCasualties.Death(human,resident);Check(WorldCasualties.Dead[human]==1&&resources.GetResourceAmount(human)==9,"Civilian death must count once");
  var military=new GameObject("QA military").AddComponent<WorldMilitaryDeploymentController>();military.enabled=false;var swords=Get<WorldMilitaryDeploymentController.UnitControl>(military,"swordsmen");swords.resource=sword;var archers=Get<WorldMilitaryDeploymentController.UnitControl>(military,"archers");archers.resource=archer;
  var killed=new GameObject("QA killed warrior");var identity=killed.AddComponent<WorldLossIdentity>();identity.resource=sword;var health=killed.AddComponent<Health>();health.TakeDamage(100000,DamageType.Physical);swords.deployed.Add(killed);
  var away=new GameObject("QA missed portal");away.AddComponent<Health>();archers.deployed.Add(away);military.SettleEscapeLosses();Check(WorldCasualties.Dead[sword]==1&&WorldCasualties.Missing[archer]==1,"Dead and missing warriors must stay separate");Check(!military.HasReturningUnits,"Settled losses must not block returning");Check(resources.GetResourceAmount(archer)==0,"Missing warrior must not be restored as a survivor");
  canvas=new GameObject("QA canvas",typeof(Canvas),typeof(CanvasScaler)).GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;var scaler=canvas.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);
  var template=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/UI/Screens/World Screen HUD.prefab").GetComponentInChildren<WorldCasualtyPopup>(true);popup=UnityEngine.Object.Instantiate(template,canvas.transform);
  var none=new Dictionary<ResourceType,int>();var dead=new Dictionary<ResourceType,int>{{human,3},{sword,2}};popup.Show(dead,none,()=>{});Check(!popup.GetComponentsInChildren<Text>().Any(t=>t.text.Contains("Не вернулись")),"Missing block must be absent for battle deaths only");
  popup.Show(none,new Dictionary<ResourceType,int>{{human,10}},()=>{});Check(!popup.GetComponentsInChildren<Text>().Any(t=>t.text.Contains("Погибли")),"Death block must be absent for missing residents only");Check(popup.GetComponentsInChildren<CanvasGroup>().Length==1,"Ten residents must collapse to an icon with a count");
  for(int i=1;i<=100;i++)Check(WorldCasualtyPopup.RevealInterval(i)<=.5f&&WorldCasualtyPopup.RevealInterval(i)*i<=2.001f,"Reveal timing cap");
  dead=new Dictionary<ResourceType,int>{{human,9},{sword,8},{archer,7}};var missing=new Dictionary<ResourceType,int>{{human,4},{sword,2},{archer,1}};
  acknowledged=false;popup.Show(dead,missing,()=>acknowledged=true);Check(!Get<Button>(popup,"okay").gameObject.activeSelf,"OK must remain hidden during reveal");Time.timeScale=0;started=EditorApplication.timeSinceStartup;EditorApplication.update+=Tick;
 }catch(Exception error){Finish(error);}}
 static void Tick(){try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup-started<2.5)return;Check(Get<Button>(popup,"okay").gameObject.activeSelf,"Unscaled reveal must finish while game is paused");Check(popup.GetComponentsInChildren<CanvasGroup>().All(g=>g.alpha==1),"Every icon must appear before OK");Capture();Get<Button>(popup,"okay").onClick.Invoke();Check(acknowledged&&!popup.gameObject.activeSelf,"OK must dismiss losses and continue to statistics");Finish(null);}catch(Exception error){Finish(error);}}
 static void Finish(Exception error){EditorApplication.update-=Tick;SessionState.SetString("WorldLossesResult",error==null?"PASS: civilian/warrior deaths once, missing warriors not restored, conditional sections, grouped counts, <=0.5 second interval and <=2 second reveal at pause, OK delayed and acknowledgement callback.":"FAIL: "+error);if(error!=null)Debug.LogException(error);if(writes!=null&&oldWrites!=null)writes.SetValue(null,oldWrites);Application.runInBackground=oldBackground;Time.timeScale=1;EditorApplication.isPlaying=false;}
 static void Capture(){var camera=new GameObject("QA camera").AddComponent<Camera>();camera.transform.position=new Vector3(0,0,-10);camera.orthographic=true;camera.cullingMask=1<<30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.04f,.03f,.06f);var rt=new RenderTexture(1440,1080,24);camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;foreach(var t in canvas.GetComponentsInChildren<Transform>(true))t.gameObject.layer=30;foreach(var g in canvas.GetComponentsInChildren<Graphic>(true))g.SetAllDirty();Canvas.ForceUpdateCanvases();camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1440,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1440,1080),0,0);image.Apply();System.IO.Directory.CreateDirectory("Art/WorldLossesQA");System.IO.File.WriteAllBytes("Art/WorldLossesQA/losses.png",image.EncodeToPNG());RenderTexture.active=previous;camera.targetTexture=null;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(image);}
}
